@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    // create left partition vertices (example size 3)
    for (int i = 0; i < 3; i++) {
        V v = (V) ("L" + i);
        target.addVertex(v);
        left.add(v);
    }
    // create right partition vertices (example size 2)
    for (int i = 0; i < 2; i++) {
        V v = (V) ("R" + i);
        target.addVertex(v);
        right.add(v);
    }
    // store sample vertices in the result map
    if (!left.isEmpty()) resultMap.put("left", left.get(0));
    if (!right.isEmpty()) resultMap.put("right", right.get(0));
    // add all edges between left and right partitions
    for (V l : left) {
        for (V r : right) {
            target.addEdge(l, r);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    Set<V> left = new HashSet<>();
    Set<V> right = new HashSet<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key.startsWith("L") || key.startsWith("left")){
            left.add(vertex);
        } else if (key.startsWith("R") || key.startsWith("right")){
            right.add(vertex);
        }
    }
    for (V u : left){
        for (V v : right){
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Separate vertices into left and right partitions based on key prefixes
    List<V> leftPart = new ArrayList<>();
    List<V> rightPart = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        if (key != null) {
            if (key.startsWith("L") || key.startsWith("l")) {
                leftPart.add(entry.getValue());
            } else if (key.startsWith("R") || key.startsWith("r")) {
                rightPart.add(entry.getValue());
            }
        }
    }
    // If no explicit prefixes, fall back to assuming two equal halves
    if (leftPart.isEmpty() && rightPart.isEmpty()) {
        int half = resultMap.size() / 2;
        int i = 0;
        for (V v : resultMap.values()) {
            if (i < half) leftPart.add(v);
            else rightPart.add(v);
            i++;
        }
    }
    // Construct the complete bipartite edges between the two partitions
    for (V leftVertex : leftPart) {
        for (V rightVertex : rightPart) {
            // Use the graph's addEdge method; if it requires an edge object,
            // create a simple edge instance or rely on the graph to create it.
            if (target instanceof UndirectedGraph) {
                ((UndirectedGraph<V, E>) target).addEdge(leftVertex, rightVertex);
            } else {
                target.addEdge(leftVertex, rightVertex);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    int half = n / 2;
    List<V> left = vertices.subList(0, half);
    List<V> right = vertices.subList(half, n);
    for (V v : vertices) {
        target.addVertex(v);
    }
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n == 0) return;
    int mid = n / 2;
    for (int i = 0; i < mid; i++) {
        V v = vertices.get(i);
        for (int j = mid; j < n; j++) {
            V u = vertices.get(j);
            // Add an edge between v and u to form a complete bipartite graph
            target.addEdge(v, u);
        }
    }
}

