public static <T> int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    buffer.clear();
    schema.writeTo(buffer, message);
    int size = buffer.position();
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);
    byte[] raw = buffer.toByteArray();
    out.write(raw, 0, size);
    buffer.clear();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int messageSize = schema.serializedSize(message, buffer);
    int temp = messageSize;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);
    schema.writeTo(buffer, message);
    byte[] data = buffer.toByteArray();
    out.write(data);
    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getCachedSize(message);
    // Write the length prefix as a varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Serialize the message
    schema.write(message, cos);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Clear the buffer before use
    buffer.clear();
    // Encode the message into the buffer
    schema.writeTo(buffer, message);
    // Size of the encoded message
    int size = buffer.position();
    // Write the size as a varint32 to the output stream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    codedOut.writeInt32NoTag(size);
    // Write the encoded message bytes to the output stream
    buffer.copyTo(out);
    return size;
}

