public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof Class<?>)) {
        return null;
    }
    Class<?> genericClass = (Class<?>) genericType;
    // Attempt to find a matching ParameterizedType in targetType hierarchy
    ParameterizedType matched = findParameterizedType(genericClass, targetType);
    if (matched == null) {
        return null;
    }
    Type[] actualArgs = matched.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Class<?> resolved = resolveClassFromType(actualArgs[i], targetType);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type resolved = resolveGenericType(args[i], targetType);
        result[i] = resolveRawArgument(resolved, targetType);
        if (result[i] == null) {
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        if (t instanceof Class<?>) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) t).getRawType();
        } else {
            // type variable or other unsupported type; cannot resolve
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    Type resolved = resolveGenericType(genericType, targetType);
    if (resolved == null) {
        return null;
    }
    return resolveRawArguments(resolved, targetType);
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] typeArgs = pt.getActualTypeArguments();
    if (typeArgs == null || typeArgs.length == 0) {
        return null;
    }
    Class<?>[] classes = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        classes[i] = resolveRawClass(typeArgs[i], targetType);
    }
    return classes;
}

