    Map<String, Object> currentMapping = ElasticsearchClient.getIndexMapping(tableName);
    // Prepare a new Mappings object to hold fields that are not present in the input
    Mappings diff = new Mappings();
    // Iterate over all fields in the current mapping
    for (Map.Entry<String, Object> entry : currentMapping.entrySet()) {
        String fieldName = entry.getKey();
        // Skip the _source field to avoid conflicts with the current index update
        if ("_source".equals(fieldName)) {
            continue;
        }
        // If the input mappings do not contain this field, add it to the diff result
        if (!mappings.containsField(fieldName)) {
            diff.addField(fieldName, entry.getValue());
        }
    }
    return diff;
}

