public Mappings diffStructure(String tableName, Mappings mappings) {
    // Fetch the complete mapping definition for the table from a schema registry or mapping service.
    Mappings fullMappings = SchemaRegistry.getMappingForTable(tableName);
    if (fullMappings == null) {
        return new Mappings();
    }
    Mappings diff = new Mappings();

    // Iterate over all defined types in the full mapping.
    for (String typeName : fullMappings.getTypeNames()) {
        MappingType fullType = fullMappings.getType(typeName);
        MappingType inputType = mappings.getType(typeName);
        MappingType diffType = new MappingType(typeName);

        // Compare each field in the full type with the input mapping.
        for (String fieldName : fullType.getFieldNames()) {
            // Skip the reserved "_source" field to avoid update conflicts.
            if ("_source".equals(fieldName)) {
                continue;
            }
            if (inputType == null || !inputType.containsField(fieldName)) {
                // Add the missing field to the diff type.
                diffType.addField(fullType.getField(fieldName));
            }
        }

        // Add the diff type only if it contains new fields.
        if (!diffType.isEmpty()) {
            diff.addType(diffType);
        }
    }

    return diff;
}

