    // Quick reference to internal byte array
    byte [] internal = this.data;
    // If both references are identical, arrays match
    if ( internal == data ) {
        return true;
    }
    // Either array null -> cannot match
    if ( internal == null || data == null ) {
        return false;
    }
    // Check bounds: offset and length must be within bounds of provided array
    if ( offset < 0 || len < 0 || offset + len > data.length ) {
        return false;
    }
    // Length of internal array must equal requested length
    if ( internal.length != len ) {
        return false;
    }
    // Compare byte-by-byte
    for ( int i = 0 ; i < len ; i++ ) {
        if ( internal[ i ] != data[ offset + i ] ) {
            return false;
        }
    }
    return true;
}

