protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    while (start < end) {
        long chunkEnd = Math.min(start + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(start, chunkEnd));
        start = chunkEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + maxDuration, end);
        ranges.add(new TimeRange(current, next));
        if (next == current) {
            break;
        }
        current = next;
    }
    return ranges;
}

