static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0 || dayStep > 31) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long monthDay = timeBucket % 10000;
    long month = monthDay / 100;
    long day = monthDay % 100;
    long stepStart = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000 + month * 100 + stepStart;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    int day   = (int)(timeBucket % 100);           // extract dd
    int month = (int)((timeBucket / 100) % 100);   // extract MM
    int year  = (int)(timeBucket / 10000);         // extract yyyy
    int startDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + startDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long startDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + startDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = day - ((day - 1) % dayStep);
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    Preconditions.checkArgument(dayStep>0,"dayStep must be positive");
    int year = (int)(timeBucket / 10000L);
    int month = (int)((timeBucket % 10000L) / 100L);
    int day = (int)(timeBucket % 100L);
    int bucketDay = day - ((day - 1) % dayStep);
    return year * 10000L + month * 100L + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end && i < str.length()) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && i + 1 < str.length()
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;       // SUPPLEMENTARY code point
            i++;              // skip low surrogate
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int size = 0;
    int start = index;
    int end = index + len;
    // Ensure bounds are valid
    int max = str.length();
    if (start < 0) {
        start = 0;
    }
    if (end > max) {
        end = max;
    }
    for (int i = start; i < end; ) {
        char ch = str.charAt(i++);
        if (ch >= 0xD800 && ch <= 0xDBFF && i < end) {
            // Potential surrogate pair
            char ch2 = str.charAt(i);
            if (ch2 >= 0xDC00 && ch2 <= 0xDFFF) {
                // Valid surrogate pair -> 4 bytes
                size += 4;
                i++; // consume low surrogate
                continue;
            }
        }
        // Determine UTF-8 byte length for the single UTF-16 code unit
        if (ch <= 0x007F) {
            size += 1;
        } else if (ch <= 0x07FF) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException();
    }
    int count = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            count += 1;
        } else if (ch <= 0x7FF) {
            count += 2;
        } else {
            if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                count += 4;
                i++; // skip low surrogate
            } else {
                count += 3;
            }
        }
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int start = Math.max(0, index);
    int end = Math.min(str.length(), start + len);
    int count = 0;
    int i = start;
    while (i < end) {
        char ch = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            cp = Character.toCodePoint(ch, str.charAt(i + 1));
            i += 2;
        } else {
            cp = ch;
            i++;
        }
        if (cp <= 0x7F) {
            count += 1;
        } else if (cp <= 0x7FF) {
            count += 2;
        } else if (cp <= 0xFFFF) {
            count += 3;
        } else {
            count += 4;
        }
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int end = index + len;
    int size = 0;
    int i = index;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

