                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                if (descriptor.charAt(i) == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
            } else {
                i++;
            }
            stack[--pos] = null;
        }
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int i = 0;
    int len = descriptor.length();
    if (descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            int slots = 1;
            char c = descriptor.charAt(i);
            if (c == 'J' || c == 'D') {
                slots = 2;
                i++;
            } else if (c == 'L') {
                // reference type: skip until ';'
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
            } else if (c == '[') {
                // array type: skip all '['
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // skip the element type (does not affect slots)
                if (i < len) {
                    if (descriptor.charAt(i) == 'L') {
                        while (i < len && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        i++; // skip ';'
                    } else {
                        i++; // primitive element type
                    }
                }
            } else {
                // primitive type
                i++;
            }
            pos -= slots;
        }
    } else {
        // single type descriptor
        int slots = 1;
        char c = descriptor.charAt(0);
        if (c == 'J' || c == 'D') {
            slots = 2;
        } else if (c == 'L') {
            while (i < len && descriptor.charAt(i) != ';') {
                i++;
            }
            i++; // skip ';'
        } else if (c == '[') {
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i < len) {
                if (descriptor.charAt(i) == 'L') {
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    i++; // primitive element
                }
            }
        }
        pos -= slots;
    }
}

private void pop(final String descriptor){
    int i = 0;
    int len = descriptor.length();
    if (len == 0) return;
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (i < len && descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            // consume array brackets
            while (c == '['){
                i++;
                c = descriptor.charAt(i);
            }
            // consume object descriptor
            if (c == 'L'){
                i++;
                while (descriptor.charAt(i) != ';') i++;
            }
            // determine how many stack slots to pop
            int slots = 1;
            if (c == 'J' || c == 'D'){
                slots = 2;
            }
            for (int s = 0; s < slots; s++){
                /* pop one slot */
                pop();
            }
            i++; // move past current type
        }
    } else {
        char c = descriptor.charAt(i);
        // consume array brackets
        while (c == '['){
            i++;
            c = descriptor.charAt(i);
        }
        // consume object descriptor
        if (c == 'L'){
            i++;
            while (descriptor.charAt(i) != ';') i++;
        }
        int slots = 1;
        if (c == 'J' || c == 'D'){
            slots = 2;
        }
        for (int s = 0; s < slots; s++){
            pop();
        }
    }
}

