            // Primitive type tag (ITEM_Integer, ITEM_Float, ITEM_Double, ITEM_Long, ITEM_Null, ITEM_UninitializedThis)
            stackMapTableEntries.putByte((Integer) type);
        } else if (type instanceof String) {
            // Object type: ITEM_Object tag (7) followed by the constant pool index of the type
            stackMapTableEntries.putByte(7);
            stackMapTableEntries.putShort(getClassIndex((String) type));
        } else if (type instanceof Uninitialized) {
            // Uninitialized type: ITEM_Uninitialized tag (8) followed by the offset
            stackMapTableEntries.putByte(8);
            stackMapTableEntries.putShort(((Uninitialized) type).offset());
        } else {
            // Default to TOP (ITEM_Top tag 0)
            stackMapTableEntries.putByte(0);
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        AbstractVerificationType type = currentFrame[i];
        stackMapTableEntries.write(type.getTag());
        switch (type.getTag()) {
            case AbstractVerificationType.OBJECT: {
                int cpIndex = type.getConstPoolIndex();
                stackMapTableEntries.write((cpIndex >> 8) & 0xFF);
                stackMapTableEntries.write(cpIndex & 0xFF);
                break;
            }
            case AbstractVerificationType.UNINITIALIZED: {
                int offset = type.getOffset();
                stackMapTableEntries.write((offset >> 8) & 0xFF);
                stackMapTableEntries.write(offset & 0xFF);
                break;
            }
            default:
                // No additional data needed for other types
                break;
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; ++i) {
        final int type = currentFrame[i];
        if (type >= 0) {
            // simple type reference
            putInt(type);
        } else {
            switch (type) {
                case -1: // Top
                    putInt(0);
                    break;
                case -2: // Integer
                    putInt(1);
                    break;
                case -3: // Float
                    putInt(2);
                    break;
                case -4: // Long
                    putInt(3);
                    break;
                case -5: // Double
                    putInt(4);
                    break;
                case -6: // Null
                    putInt(5);
                    break;
                case -7: // UninitializedThis
                    putInt(6);
                    break;
                default:
                    // Uninitialized object: the value holds its offset
                    putInt(7);
                    putShort(type);
                    break;
            }
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        // Retrieve the abstract type from the current frame at this position
        AbstractType type = currentFrame.get(i);
        // Serialize this type into the stackMapTableEntries buffer following the
        // JVMS verification_type_info format used by StackMapTable attributes.
        stackMapTableEntries.writeVerificationTypeInfo(type);
    }
}

