    int loc0 = Arrays.binarySearch(primeCapacities, desiredCapacity);
    if (loc0 < 0) {
        loc0 = -loc0 - 1;
    }
    int result = primeCapacities[loc0];
    if (desiredCapacity >= 1000 && result > desiredCapacity * 111 / 100) {
        if (loc0 > 0) {
            return primeCapacities[loc0 - 1];
        }
    }
    return result;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2){
        return 2;
    }
    int start = desiredCapacity;
    if (start % 2 == 0){
        start++;
    }
    int upper = start;
    if (start >= 1000){
        upper = (int)(start * 1.11);
    }
    for (int n = start; n <= upper; n += 2){
        boolean prime = true;
        for (int i = 2; i <= Math.sqrt(n); i++){
            if (n % i == 0){
                prime = false;
                break;
            }
        }
        if (prime){
            return n;
        }
    }
    for (int n = upper | 1; ; n += 2){
        boolean prime = true;
        for (int i = 2; i <= Math.sqrt(n); i++){
            if (n % i == 0){
                prime = false;
                break;
            }
        }
        if (prime){
            return n;
        }
    }
}

