            result.put(key, buildContent(elem.getAsJsonObject()));
        } else if (elem.isJsonArray()) {
            List<Object> list = new ArrayList<>();
            for (JsonElement e : elem.getAsJsonArray()) {
                if (e.isJsonObject()) {
                    list.add(buildContent(e.getAsJsonObject()));
                } else if (e.isJsonArray()) {
                    list.add(e.getAsJsonArray());
                } else if (e.isJsonPrimitive()) {
                    JsonPrimitive p = e.getAsJsonPrimitive();
                    if (p.isNumber()) {
                        list.add(p.getAsNumber());
                    } else if (p.isBoolean()) {
                        list.add(p.getAsBoolean());
                    } else {
                        list.add(p.getAsString());
                    }
                } else if (e.isJsonNull()) {
                    list.add(null);
                }
            }
            result.put(key, list);
        } else if (elem.isJsonNull()) {
            result.put(key, null);
        }
    }
    if (jsonObject.has("ats")) {
        result.put("ats", jsonObject.get("ats").isJsonPrimitive()
                ? jsonObject.get("ats").getAsJsonPrimitive().getAsString()
                : jsonObject.get("ats"));
    }
    return result;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    for (Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement element = entry.getValue();
        Object value;
        if (element.isJsonPrimitive()){
            JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isBoolean()){
                value = prim.getAsBoolean();
            }else if (prim.isNumber()){
                value = prim.getAsNumber();
            }else{
                value = prim.getAsString();
            }
        }else if (element.isJsonObject()){
            value = buildContent(element.getAsJsonObject());
        }else if (element.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for (JsonElement e : element.getAsJsonArray()){
                if (e.isJsonPrimitive()){
                    JsonPrimitive prim = e.getAsJsonPrimitive();
                    if (prim.isBoolean()){
                        list.add(prim.getAsBoolean());
                    }else if (prim.isNumber()){
                        list.add(prim.getAsNumber());
                    }else{
                        list.add(prim.getAsString());
                    }
                }else if (e.isJsonObject()){
                    list.add(buildContent(e.getAsJsonObject()));
                }else{
                    list.add(null);
                }
            }
            value = list;
        }else{
            value = null;
        }
        content.put(key, value);
    }
    return content;
}

