public final byte[] toByteArray() {
    int totalSize = 0;
    for (ByteBuffer buf : mBuffers) {
        totalSize += buf.remaining();
    }
    byte[] result = new byte[totalSize];
    int pos = 0;
    for (ByteBuffer buf : mBuffers) {
        ByteBuffer dup = buf.duplicate();
        dup.get(result, pos, dup.remaining());
        pos += dup.remaining();
    }
    return result;
}

