            sb.append('\\');
            i++; // skip the next backslash
            continue;
        }
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case 'u':
                if (i + 6 <= length) {
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        sb.append((char) value);
                        i += 5; // skip 'u' and four hex digits
