            if(pair != null && pair.getKey() != null){
                Object val = pair.getValue();
                if(val == null){
                    builder.addNull(pair.getKey());
                }else if(val instanceof String){
                    builder.add(pair.getKey(), (String) val);
                }else if(val instanceof Number){
                    builder.add(pair.getKey(), (Number) val);
                }else if(val instanceof Boolean){
                    builder.add(pair.getKey(), (Boolean) val);
                }else if(val instanceof Collection){
                    JsonArrayBuilder arrBuilder = Json.createArrayBuilder();
                    for(Object element : (Collection<?>) val){
                        if(element instanceof String){
                            arrBuilder.add((String) element);
                        }else if(element instanceof Number){
                            arrBuilder.add((Number) element);
                        }else if(element instanceof Boolean){
                            arrBuilder.add((Boolean) element);
                        }else{
                            arrBuilder.add(element.toString());
                        }
                    }
                    builder.add(pair.getKey(), arrBuilder);
                }else{
                    builder.add(pair.getKey(), val.toString());
                }
            }
        }
    }
    return builder.build();
}

private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObjectBuilder builder = Json.createObjectBuilder();
    if (properties != null) {
        for (KeyStringValuePair kv : properties) {
            if (kv != null) {
                String key = kv.getKey();
                Object value = kv.getValue();
                if (value == null) {
                    builder.addNull(key);
                } else if (value instanceof String) {
                    builder.add(key, (String) value);
                } else if (value instanceof Number) {
                    builder.add(key, ((Number) value).doubleValue());
                } else if (value instanceof Boolean) {
                    builder.add(key, (Boolean) value);
                } else {
                    builder.add(key, value.toString());
                }
            }
        }
    }
    return builder.build();
}

private JsonObject convertProperties(List<KeyStringValuePair> properties) {
