        String key = pair.getKey();
        Object value = pair.getValue();
        if (value == null) {
            continue;
        }
        if (value instanceof String) {
            json.addProperty(key, (String) value);
        } else if (value instanceof Number) {
            json.addProperty(key, (Number) value);
        } else if (value instanceof Boolean) {
            json.addProperty(key, (Boolean) value);
        } else {
            json.add(key, new JsonPrimitive(value.toString()));
        }
    }
    return json;
}

int removeUnusedNodes() {
    int count = 0;
    if (root == null) {
        return 0;
    }
    if (!root.isActive()) {
        root = null;
        return 1;
    }
    java.util.Deque<java.util.List<Category>> stack = new java.util.ArrayDeque<>();
    stack.push(root.getChildren());
    while (!stack.isEmpty()) {
        java.util.Iterator<Category> it = stack.pop().iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                count++;
            } else {
                stack.push(child.getChildren());
            }
        }
    }
    return count;
}

