protected int removeUnusedNodes(){
    int removedCount = 0;
    if(rootCategory == null) return removedCount;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(rootCategory);
    while(!stack.isEmpty()){
        Category current = stack.pop();
        for(Category child : current.getChildren()){
            stack.push(child);
        }
        if(!current.isActive()){
            Category parent = current.getParent();
            if(parent != null){
                parent.removeChild(current);
            }else{
                rootCategory = null;
            }
            removedCount++;
        }
    }
    return removedCount;
}

