    return removeUnusedNodesRec(root);
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    Deque<Category[]> stack = new ArrayDeque<>();
    stack.addFirst(new Category[] { root, null });
    while (!stack.isEmpty()) {
        Category[] pair = stack.removeFirst();
        Category node = pair[0];
        Category parent = pair[1];
        if (!node.isActive()) {
            if (parent != null) {
                parent.getChildren().remove(node);
                removedCount++;
            } else {
                // If the root itself is inactive, drop the entire tree
                root = null;
                removedCount++;
            }
        } else {
            for (Category child : node.getChildren()) {
                stack.addFirst(new Category[] { child, node });
            }
        }
    }
    return removedCount;
}

