final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the start offset of the CONSTANT_Utf8 entry in the class file buffer.
    int offset = 10; // constant pool starts after magic(4)+minor(2)+major(2)+constant_pool_count(2)
    // Scan constant pool entries up to the requested index.
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        // The first byte of each entry is the tag.
        int tag = classFileBuffer[offset] & 0xFF;
        offset++; // Move past the tag.
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int utfLen = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + utfLen;
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // These take up two indices in the constant pool.
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    // Now offset points at the tag byte of the desired CONSTANT_Utf8 entry.
    // Skip the tag byte itself (already read in loop above for others, but not for target).
    int start = offset;
    int tag = classFileBuffer[start] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    start++; // Move past the tag.
    // Read the length of the modified UTF-8 string.
    int utfLength = ((classFileBuffer[start] & 0xFF) << 8) | (classFileBuffer[start + 1] & 0xFF);
    start += 2; // Position at the first byte of the string data.

    // Ensure the supplied char buffer is large enough.
    if (charBuffer.length < utfLength) {
        throw new IllegalArgumentException("Provided char buffer is not large enough");
    }

    // Decode the modified UTF-8 bytes into the supplied char buffer.
    java.nio.charset.CharsetDecoder decoder =
        java.nio.charset.Charset.forName("UTF-8").newDecoder();
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, start, utfLength);
    java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
    try {
        decoder.decode(byteBuf, charBuf, true);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new IllegalArgumentException("Failed to decode UTF-8 entry at index " + constantPoolEntryIndex, e);
    }

    // The string is now in charBuffer[0..utfLength-1].
    return new String(charBuffer, 0, utfLength);
}

