    // Flag byte must be CONSTANT_Utf8 (value 1)
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException(
            "Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    // The next two bytes give the UTF-8 length
    final int length =
        ((classFileBuffer[offset + 1] & 0xFF) << 8)
        | (classFileBuffer[offset + 2] & 0xFF);
    final int start = offset + 3; // first byte of the UTF-8 string
    if (charBuffer.length < length) {
        throw new IllegalArgumentException(
            "Provided char buffer is too small; required " + length);
    }
    // Convert the raw UTF‑8 bytes into a Java String
    final String result =
        new String(classFileBuffer, start, length, "UTF-8");
