    final int offset = constantPoolEntryOffsets[constantPoolEntryIndex];
    final int byteLength = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
    if (charBuffer.length < (byteLength * 2)) {
        throw new IllegalArgumentException("char buffer too small for UTF-8");
    }
    int bytePos = offset + 2;
    int charPos = 0;
    for (int i = 0; i < byteLength; ) {
        int b = classFileBuffer[bytePos++] & 0xFF;
        if ((b & 0x80) == 0) {
            charBuffer[charPos++] = (char)b;
        } else if ((b & 0xE0) == 0xC0) {
            int b2 = classFileBuffer[bytePos++] & 0xFF;
            int ch = ((b & 0x1F) << 6) | (b2 & 0x3F);
            charBuffer[charPos++] = (char)ch;
        } else if ((b & 0xF0) == 0xE0) {
            int b2 = classFileBuffer[bytePos++] & 0xFF;
            int b3 = classFileBuffer[bytePos++] & 0xFF;
            int ch = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            charBuffer[charPos++] = (char)ch;
        } else {
            throw new IllegalArgumentException("invalid modified UTF-8 encoding");
        }
        i++;
    }
    return new String(charBuffer, 0, charPos);
}

