private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // If no start node, return null circulator (or throw? using null for simplicity)
    if (start == null) {
        return null;
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // Immediate check on the starting node
    if (stop != null && circ.getNode().equals(stop)) {
        return circ;
    }
    if (predicate != null && predicate.test(circ.getNode())) {
        return circ;
    }

    // Use a set to detect loops and prevent infinite traversal
    Set<Node> visited = Collections.newSetFromMap(new IdentityHashMap<>());
    visited.add(circ.getNode());

    while (true) {
        // Advance the circulator in the specified direction
        circ.next(dir);
        Node current = circ.getNode();

        if (current == null) {
            break; // traversal ended unexpectedly
        }

        if (stop != null && current.equals(stop)) {
            return circ; // reached the stop node
        }

        if (predicate != null && predicate.test(current)) {
            return circ; // predicate satisfied
        }

        // If we revisit a node that was already visited, break to avoid infinite loop
        if (!visited.add(current)) {
            break;
        }
    }

    // Fallback to the last circulator (could be stop or loop back)
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    OuterFaceCirculator circ = new OuterFaceCirculator(start,dir);
    while (!circ.node().equals(stop)){
        if (predicate.test(circ.node())){
            return circ;
        }
        circ.next();
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }
        current = dir > 0 ? current.nextOnOuterFace() : current.prevOnOuterFace();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true) {
        Node current = circ.current();
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            break;
        }
        circ.move(dir);
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = circulator.node();
    while (!current.equals(stop)) {
        if (predicate.test(current)) {
            break;
        }
        circulator.next();
        current = circulator.node();
    }
    return circulator;
}

