private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.util.List<Integer> indices = new java.util.ArrayList<>();
        for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
            ShardingKey key = field.getAnnotation(ShardingKey.class);
            if (key != null) {
                indices.add(key.index());
            }
        }
        if (!indices.isEmpty()) {
            java.util.Collections.sort(indices);
            for (int i = 0; i < indices.size(); i++) {
                if (indices.get(i) != i) {
                    throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model not found: " + modelName, e);
    }
}

private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.lang.reflect.Field[] fields = clazz.getDeclaredFields();
        java.util.Set<Integer> indices = new java.util.HashSet<>();
        for (java.lang.reflect.Field f : fields) {
            // Assume the sharding key annotation is named ShardingKey with an index property
            java.lang.annotation.Annotation anno = f.getAnnotation(ShardingKey.class);
            if (anno != null) {
                int idx = (int) anno.annotationType().getMethod("index").invoke(anno);
                indices.add(idx);
            }
        }
        if (indices.isEmpty()) {
            return; // nothing to check
        }
        int min = java.util.Collections.min(indices);
        int max = java.util.Collections.max(indices);
        if (indices.size() != max - min + 1) {
            throw new IllegalStateException("Sharding key indices are not continuous for " + modelName);
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to check sharding key indices for " + modelName, e);
    }
}

