}

private void check(String modelName) throws IllegalStateException {
    // Attempt to read sharding key indices for the given model from an environment variable.
    String envKey = "SHARD_KEY_INDICES_" + modelName.toUpperCase();
    String indicesStr = System.getenv(envKey);
    if (indicesStr == null || indicesStr.isEmpty()) {
        // Nothing to validate.
        return;
    }
    String[] tokens = indicesStr.split(",");
    int prev = -1;
    for (String token : tokens) {
        int idx;
        try {
            idx = Integer.parseInt(token.trim());
        } catch (NumberFormatException e) {
            throw new IllegalStateException(
                "Invalid sharding key index format for model " + modelName + ": " + token, e);
        }
        if (prev != -1 && idx != prev + 1) {
            throw new IllegalStateException(
                "Sharding key indices are not continuous for model " + modelName);
        }
        prev = idx;
    }
}

private void check(String modelName) throws IllegalStateException {
