    }
    // Build adjacency mapping
    Map<V, List<E>> adjacency = new HashMap<V, List<E>>();
    for (E e : tour) {
        V v1 = graph.getEdgeSource(e);
        V v2 = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(v1, k -> new ArrayList<E>()).add(e);
        adjacency.computeIfAbsent(v2, k -> new ArrayList<E>()).add(e);
    }
    // Start with an arbitrary edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;
    Set<E> remaining = new HashSet<E>(tour);
    List<E> pathEdges = new ArrayList<E>();
    // Iterate until all edges are used
    while (!remaining.isEmpty()) {
        List<E> edgesAtCurrent = adjacency.get(currentVertex);
        if (edgesAtCurrent == null) {
            break; // cannot continue
        }
        E chosen = null;
        for (E e : edgesAtCurrent) {
            if (remaining.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            break; // no available edge
        }
        remaining.remove(chosen);
        pathEdges.add(chosen);
        V otherVertex = graph.getEdgeSource(chosen).equals(currentVertex)
                ? graph.getEdgeTarget(chosen)
                : graph.getEdgeSource(chosen);
        currentVertex = otherVertex;
    }
    // Compute total weight
    double totalWeight = 0.0;
    for (E e : pathEdges) {
        totalWeight += graph.getEdgeWeight(e);
    }
    V endVertex = currentVertex;
    return new GraphPathImpl<V, E>(graph, startVertex, endVertex, pathEdges, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();

    // pick arbitrary starting edge
    Iterator<E> it = tour.iterator();
    E first = it.next();
    V start = graph.getEdgeSource(first);
    V end = graph.getEdgeTarget(first);
    V current = start;
    vertexList.add(current);
    edgeList.add(first);
    it.remove();

    // continue with the other endpoint
    current = end;
    vertexList.add(current);

    // follow edges until exhausted
    while (!tour.isEmpty()) {
        E nextEdge = null;
        for (E e : tour) {
            if (graph.getEdgeSource(e).equals(current) || graph.getEdgeTarget(e).equals(current)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            // malformed tour
            break;
        }
        tour.remove(nextEdge);
        edgeList.add(nextEdge);
        V v1 = graph.getEdgeSource(nextEdge);
        V v2 = graph.getEdgeTarget(nextEdge);
        current = v1.equals(current) ? v2 : v1;
        vertexList.add(current);
    }

    double weight = 0.0;
    return new GraphWalk<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) return null;
    Map<V, List<E>> sourceToEdges = new HashMap<>();
    Set<V> targets = new HashSet<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        sourceToEdges.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        targets.add(tgt);
    }
    V start = null;
    for (V v : sourceToEdges.keySet()) {
        if (!targets.contains(v)) {
            start = v;
            break;
        }
    }
    if (start == null) {
        start = sourceToEdges.keySet().iterator().next();
    }
    List<E> ordered = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    V cur = start;
    while (!remaining.isEmpty()) {
        List<E> list = sourceToEdges.get(cur);
        if (list == null) break;
        E chosen = null;
        for (E e : list) {
            if (remaining.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) break;
        ordered.add(chosen);
        remaining.remove(chosen);
        cur = graph.getEdgeTarget(chosen);
    }
    V end = cur;
    double weight = graph.getPathWeight(ordered);
    return new DefaultGraphPath<>(graph, start, end, weight, ordered);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    V startVertex = null;
    if (!tour.isEmpty()) {
        startVertex = graph.getEdgeSource(tour.iterator().next());
    }
    List<E> orderedEdges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    V current = startVertex;
    while (!remaining.isEmpty()) {
        List<E> edgesAt = adjacency.get(current);
        if (edgesAt == null) break;
        E chosen = null;
        for (E e : edgesAt) {
            if (remaining.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) break;
        orderedEdges.add(chosen);
        remaining.remove(chosen);
        V next = graph.getEdgeSource(chosen).equals(current) ? graph.getEdgeTarget(chosen) : graph.getEdgeSource(chosen);
        current = next;
    }
    List<V> vertexList = new ArrayList<>();
    V v = startVertex;
    vertexList.add(v);
    for (E e : orderedEdges) {
        V next = graph.getEdgeSource(e).equals(v) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
        vertexList.add(next);
        v = next;
    }
    double totalWeight = 0.0;
    for (E e : orderedEdges) {
        totalWeight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, startVertex, startVertex, vertexList, orderedEdges, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    // Create a mutable copy of the set so we can remove edges as we traverse.
    Set<E> remaining = new HashSet<>(tour);
    // Start with an arbitrary edge from the set.
    Iterator<E> it = remaining.iterator();
    E currentEdge = it.next();
    remaining.remove(currentEdge);

    // List that will hold the ordered edges of the tour.
    List<E> ordered = new ArrayList<>();
    ordered.add(currentEdge);

    // The vertex where the current traversal ends.
    V nextVertex = graph.getEdgeTarget(currentEdge);

    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> remIt = remaining.iterator();
        while (remIt.hasNext()) {
            E e = remIt.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            // If the edge is directed, we only accept it if it continues from nextVertex.
            // For undirected graphs we also accept the reverse direction.
            if (src.equals(nextVertex)) {
                ordered.add(e);
                nextVertex = tgt;
                remIt.remove();
                found = true;
                break;
            } else if (tgt.equals(nextVertex)) {
                ordered.add(e);
                nextVertex = src;
                remIt.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            // Can't continue the tour with the remaining edges.
            return null;
        }
    }

    double weight = 0.0;
    for (E e : ordered) {
        weight += graph.getEdgeWeight(e);
    }

    V source = graph.getEdgeSource(currentEdge);
    V target = nextVertex;
    return new DefaultGraphPath<>(graph, source, target, ordered, weight);
}

