int addConstantNameAndType(final String name,final String descriptor){
    int nameIdx;
    int descrIdx;
    // Look up or add the UTF8 entries for the name and descriptor
    nameIdx = findUtf8(name);
    if(nameIdx == NOT_FOUND){
        nameIdx = addUtf8(name);
    }
    descrIdx = findUtf8(descriptor);
    if(descrIdx == NOT_FOUND){
        descrIdx = addUtf8(descriptor);
    }
    // Search for an existing NameAndType entry with the same name and descriptor indices
    for(int loc = 1; loc < maxPoolSize; loc++){
        if(types[loc] == NAME_AND_TYPE){
            if(readNameAndTypeNameIndex(loc) == nameIdx && 
               readNameAndTypeDescriptorIndex(loc) == descrIdx){
                return loc; // already exists
            }
        }
    }
    // Add a new NameAndType entry to the constant pool
    int newIndex = ++maxPoolSize;
    types[newIndex] = NAME_AND_TYPE;
    // Ensure the byteCode array has enough space: tag (1 byte) + two u2 indices = 5 bytes
    int currentLen = byteCode.length;
    byteCode = java.util.Arrays.copyOf(byteCode, currentLen + 5);
    byteCode[currentLen] = NAME_AND_TYPE; // tag
    writeU2(byteCode, currentLen + 1, nameIdx); // name_index
    writeU2(byteCode, currentLen + 3, descrIdx); // descriptor_index
    offsets[newIndex] = currentLen; // record the start offset of this entry
    return newIndex;
}

int addConstantNameAndType(final String name, final String descriptor){
    int nameIdx = findUtf8(name);
    int descIdx = findUtf8(descriptor);
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nIdx = offsets[i];
            int dIdx = offsets[i + 1];
            if (nIdx == nameIdx && dIdx == descIdx) {
                return i;
            }
        }
    }
    int loc = maxPoolSize;
    types[loc] = NAME_TYPE;
    offsets[loc] = nameIdx;
    offsets[loc + 1] = descIdx;
    maxPoolSize = loc + 2;
    return loc;
}

int addConstantNameAndType(final String name,final String descriptor){
    int idx = findNameAndType(name, descriptor);
    if(idx != NOT_FOUND) return idx;
    return appendNameAndType(name, descriptor);
}

int addConstantNameAndType(final String name,final String descriptor){
    int nameIndex = findUtf8(name);
    if (nameIndex == NOT_FOUND) {
        nameIndex = addUtf8(name);
    }
    int descIndex = findUtf8(descriptor);
    if (descIndex == NOT_FOUND) {
        descIndex = addUtf8(descriptor);
    }
    int key = (nameIndex << 16) | descIndex;
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE && offsets[i] == key) {
            return i;
        }
    }
    ++maxPoolSize;
    types[maxPoolSize] = NAME_TYPE;
    offsets[maxPoolSize] = key;
    return maxPoolSize;
}

int addConstantNameAndType(final String name, final String descriptor){
    int loc0 = findNameAndType(name, descriptor);
    if (loc0 != NOT_FOUND) {
        return loc0;
    }
    // add UTF-8 constants for name and descriptor
    int nameIdx = addUtf8(name);
    int descIdx = addUtf8(descriptor);
    // append a new CONSTANT_NameAndType_info entry
    appendNameAndType(nameIdx, descIdx);
    // return index of the newly added entry
    return findNameAndType(name, descriptor);
}

private String unescapeId(String input){
    if (input == null) {
