    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                sb.append(input.charAt(++i));
            } else {
                sb.append('\\');
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

