private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; ) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char next = input.charAt(i + 1);
                if (next >= '0' && next <= '7') {
                    int val = Character.digit(next, 8);
                    int digits = 1;
                    while (i + digits + 1 < len && digits < 3 &&
                           input.charAt(i + digits + 1) >= '0' && input.charAt(i + digits + 1) <= '7') {
                        val = val * 8 + Character.digit(input.charAt(i + digits + 1), 8);
                        digits++;
                    }
                    sb.append((char) val);
                    i += digits + 1; // skip backslash and octal digits
                } else {
                    sb.append(next); // escape non-digit character
                    i += 2; // skip backslash and next character
                }
            } else {
                // trailing backslash: just keep it
                sb.append('\\');
                i++;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

