private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel == 0) {
        // Nothing to move if the minimum label is already 0
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return; // Nothing to move
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<Integer>();
        bucketsByLabel.set(0, target);
    }
    for (Integer vertex : source) {
        target.add(vertex);
        labels.set(vertex, 0);
    }
    source.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> minSet = bucketsByLabel.get(minLabel);
    if (minSet == null || minSet.isEmpty()) {
        return;
    }
    Set<Integer> zeroSet = bucketsByLabel.get(0);
    if (zeroSet == null) {
        zeroSet = new HashSet<>();
        if (bucketsByLabel.size() > 0) {
            bucketsByLabel.set(0, zeroSet);
        } else {
            bucketsByLabel.add(zeroSet);
        }
    }
    // Use a copy to avoid ConcurrentModificationException if minSet is same as zeroSet
    Set<Integer> copy = new HashSet<>(minSet);
    for (Integer vertex : copy) {
        zeroSet.add(vertex);
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    minSet.clear();
}

