    if (list == null || this == list) return;
    // If source list is empty, nothing to move
    if (list.head == null) return;

    // Capture nodes and size from source
    ListNode<E> first = list.head;
    ListNode<E> last = list.tail;
    int movedCount = list.size;

    // Detach source list
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Merge into destination list
    if (this.head == null) {
        this.head = first;
        this.tail = last;
    } else {
        this.tail.next = first;
        first.prev = this.tail;
        this.tail = last;
    }
    this.size += movedCount;
}

