    if (name == null) return;
    if (nameStart < 0 || nameStart >= name.length()) return;
    String sub = name.substring(nameStart);
    java.util.StringTokenizer st = new java.util.StringTokenizer(sub);
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (!token.isEmpty()) {
            buf.append(Character.toUpperCase(token.charAt(0)));
        }
    }
}

