    int len = name.length();
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= len) {
        return;
    }
    boolean newWord = true;
    for (int i = start; i < len; i++) {
        char c = name.charAt(i);
        if (Character.isWhitespace(c)) {
            newWord = true;
        } else if (newWord) {
            buf.append(c);
