private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort((a,b) -> ((Comparable<Object>)a).compareTo(b));
    for (K key : keys){
        int idx = Collections.binarySearch(sorted, key, (a,b) -> ((Comparable<Object>)a).compareTo(b));
        if (idx < 0){
            idx = -idx - 2;
        } else {
            while (idx + 1 < sorted.size() && ((Comparable<Object>)sorted.get(idx + 1)).compareTo(key) == 0){
                idx++;
            }
        }
        if (idx < 0){
            result.add(-1);
        } else {
            result.add(idx);
        }
    }
    return result;
}

