private void pop(final String descriptor){
    int slots = 0;
    int i = 0;
    int len = descriptor.length();
    if (len == 0) return;
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (i < len && descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            if (c == 'L'){
                i = descriptor.indexOf(';', i);
                if (i == -1) throw new IllegalArgumentException("Invalid descriptor");
                i++;
                slots += 1;
            } else if (c == '['){
                while (i < len && descriptor.charAt(i) == '[') i++;
                if (i < len && descriptor.charAt(i) == 'L'){
                    i = descriptor.indexOf(';', i);
                    if (i == -1) throw new IllegalArgumentException("Invalid descriptor");
                    i++;
                } else {
                    i++;
                }
                slots += 1;
            } else if (c == 'J' || c == 'D'){
                slots += 2;
                i++;
            } else {
                slots += 1;
                i++;
            }
        }
    } else {
        char c = descriptor.charAt(0);
        if (c == 'L'){
            int semicolon = descriptor.indexOf(';', 0);
            if (semicolon == -1) throw new IllegalArgumentException("Invalid descriptor");
            slots += 1;
        } else if (c == '['){
            while (i < len && descriptor.charAt(i) == '[') i++;
            if (i < len && descriptor.charAt(i) == 'L'){
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) throw new IllegalArgumentException("Invalid descriptor");
                i = semicolon + 1;
            } else {
                i++;
            }
            slots += 1;
        } else if (c == 'J' || c == 'D'){
            slots += 2;
        } else {
            slots += 1;
        }
    }
    for (int j = 0; j < slots; j++){
        --pos;
    }
}

