    }
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop only the argument types
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'Z':
                case 'B':
                case 'C':
                case 'S':
                case 'I':
