                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                    pos--;
                    break;
                case '[':
                    i++; // skip '[' and loop again to consume the type element
                    break;
                default:
                    i++;
            }
        }
        // Skip the ')' and the return type
    } else {
        // Type descriptor: pop this type
        while (i < len) {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'Z':
                case 'B':
                case 'C':
                case 'S':
                case 'I':
