public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    boolean isAbsolute = path.startsWith("/");
    for (String p : pathParts) {
        if (!p.isEmpty()) {
            parts.add(p);
        }
    }
    for (String r : relParts) {
        if (r.isEmpty() || r.equals(".")) {
            continue;
        } else if (r.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            }
        } else {
            parts.add(r);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if (i < parts.size() - 1) {
            sb.append("/");
        }
    }
    if (parts.isEmpty() && isAbsolute) {
        return "/";
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
        if (relativePath == null || relativePath.isEmpty()) {
            return path;
        }
        // split base path, ignoring empty components caused by leading '/'
        String[] baseParts = path.split("/");
        java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                stack.addLast(part);
            }
        }
        // process relative components
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue; // skip empty or current dir
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast(); // go up a level
                }
                continue;
            }
            stack.addLast(part); // add normal directory/file
        }

        // Rebuild the path
        StringBuilder result = new StringBuilder();
        boolean isAbsolute = path.startsWith("/");
        if (isAbsolute) {
            result.append("/");
        }
        boolean first = true;
        for (String dir : stack) {
            if (!first) {
                result.append("/");
            }
            result.append(dir);
            first = false;
        }

        // If the result is empty but the original path was absolute,
        // then the result should be the root "/"
        if (result.length() == 0 && isAbsolute) {
            result.append("/");
        }

        return result.toString();
    }

public static String applyRelativePath(String path, String relativePath) {
    // Use a deque as a stack of path components
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    // Handle leading slash
    boolean hasRoot = path.startsWith("/");
    if (hasRoot) {
        // Represent the root with an empty string token
        stack.addLast("");
    }

    // Split the base path and push components onto the stack
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !(stack.getLast().equals(""))) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Process the relative path components
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !(stack.getLast().equals(""))) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Reconstruct the resulting path
    StringBuilder result = new StringBuilder();
    for (String token : stack) {
        if (!token.isEmpty()) {
            // Add separator before each non-root token
            result.append("/");
            result.append(token);
        } else {
            // Root token, ensure leading slash
            if (result.length() == 0) {
                result.append("/");
            }
        }
    }

    // Handle the case when result is empty (e.g., resolving "./" on root)
    if (result.length() == 0) {
        return hasRoot ? "/" : ".";
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    boolean leadingSlash = path.startsWith("/");
    // split the path and take the parent directory (exclude the last segment)
    String[] pathSegments = path.split("/");
    LinkedList<String> stack = new LinkedList<>();
    for (int i = 0; i < pathSegments.length; i++) {
        String seg = pathSegments[i];
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        // Treat the last segment as a possible file name and remove it
        if (i == pathSegments.length - 1 && !path.endsWith("/")) {
            continue;
        }
        stack.addLast(seg);
    }

    // process the relative path components
    String[] relSegments = relativePath.split("/");
    for (String seg : relSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        } else if (seg.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }

    // rebuild the resolved path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    result.append(String.join("/", stack));
    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    java.util.LinkedList<String> segments = new java.util.LinkedList<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            segments.add(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String rel : relParts) {
        if (rel.isEmpty() || rel.equals(".")) {
            continue;
        }
        if (rel.equals("..")) {
            if (!segments.isEmpty()) {
                segments.removeLast();
            } else if (!isAbsolute) {
                // preserve leading ".." for relative paths
                segments.addFirst("..");
            }
        } else {
            segments.add(rel);
        }
    }
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    boolean first = true;
    for (String seg : segments) {
        if (!first) {
            result.append("/");
        }
        result.append(seg);
        first = false;
    }
    if (result.length() == 0 && !isAbsolute) {
        // If nothing was added, return current directory
        return ".";
    }
    return result.toString();
}

