    Node fromNode = (_currentNode.isVirtual() ? _currentNode.getRealNode() : _currentNode);
    Node toNode = (_nextNode.isVirtual() ? _nextNode.getRealNode() : _nextNode);

    // Search for an edge that connects the resolved nodes
    for (Edge e : this._edges) {
        if ((e.getFrom() == fromNode && e.getTo() == toNode) ||
