public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Protocol buffer failed to parse a varint.");
}

