public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Assume each line is a serialized ThreadSnapshot representation
            ThreadSnapshot snapshot = ThreadSnapshot.fromString(line);
            long snapshotTime = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshotTime >= range.getStartTime() && snapshotTime <= range.getEndTime()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            // assume each line starts with a timestamp followed by a space and the snapshot data
            String[] parts = line.split("\\s+", 2);
            long ts = Long.parseLong(parts[0]);
            for (ProfileAnalyzeTimeRange tr : timeRanges) {
                if (ts >= tr.getStartMillis() && ts <= tr.getEndMillis()) {
                    String data = parts.length > 1 ? parts[1] : "";
                    snapshots.add(new ThreadSnapshot(data));
                    break;
                }
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> function(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    List<String> lines = Files.readAllLines(file.toPath());
    for (String line : lines) {
        ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range.contains(snapshot.getTimestamp())) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,
