    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists()) {
        return result;
    }
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume each line is a serialized ThreadSnapshot and provides a static parse method.
            ThreadSnapshot tsnap;
            try {
                tsnap = ThreadSnapshot.parseFrom(line);
            } catch (Exception e) {
                // Skip malformed line
                continue;
            }
            long ts = tsnap.getTimestamp(); // Assume ThreadSnapshot has getTimestamp()
            boolean withinRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                withinRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                        withinRange = true;
                        break;
                    }
                }
            }
            if (withinRange) {
                result.add(tsnap);
            }
        }
    }
    return result;
}

